/**
 * The Worker entry (wrangler.jsonc `main`). It wraps OpenNext's generated handler with Sentry,
 * so errors are reported with personal data stripped (ADR 0002, issue #9). Background jobs
 * (#10) add their `scheduled` and `queue` handlers here.
 *
 * Only this file imports @sentry/cloudflare at runtime: the SDK needs `cloudflare:workers`,
 * which Node (next dev, Playwright, Vitest) doesn't have.
 */
import { captureException, withSentry } from "@sentry/cloudflare";
// @ts-expect-error: generated by `opennextjs-cloudflare build`; wrangler resolves it at deploy.
import openNext from "./.open-next/worker.js";
import { registerErrorReporter, sentryOptions, type SentryEnv } from "./src/modules/observability";

registerErrorReporter((error, tags) => captureException(error, { tags }));

const handler: ExportedHandler<CloudflareEnv & SentryEnv> = {
  fetch: (request, env, ctx) =>
    (openNext as ExportedHandler<CloudflareEnv>).fetch!(request, env, ctx),
};

export default withSentry((env: CloudflareEnv & SentryEnv) => sentryOptions(env), handler);
